{"command":"python3 -c "
import http.server, socketserver, threading, subprocess, pty, os

class Handler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(b'{\"hello\": \"world\"}')

server = socketserver.TCPServer(('127.0.0.1', 8906), Handler)
t = threading.Thread(target=server.serve_forever)
t.daemon = True
t.start()

def run_combo(out_tty, err_tty, args):
    m_out, s_out = (pty.openpty() if out_tty else (None, None))
    m_err, s_err = (pty.openpty() if err_tty else (None, None))

    stdout_fd = s_out if out_tty else subprocess.PIPE
    stderr_fd = s_err if err_tty else subprocess.PIPE

    p = subprocess.Popen(['./executable'] + args, stdout=stdout_fd, stderr=stderr_fd, close_fds=True)
    if out_tty: os.close(s_out)
    if err_tty: os.close(s_err)

    if out_tty:
        out = os.read(m_out, 10240).decode('utf-8', errors='replace')
        os.close(m_out)
    else:
        out = p.stdout.read().decode('utf-8')

    if err_tty:
        err = os.read(m_err, 10240).decode('utf-8', errors='replace')
        os.close(m_err)
    else:
        err = p.stderr.read().decode('utf-8')

    p.wait()
    print(f'out_tty={out_tty}, err_tty={err_tty}, args={args}:')
    print('  STDOUT:', repr(out))
    print('  STDERR:', repr(err))

for args in [['http://127.0.0.1:8906/'], ['-i', 'http://127.0.0.1:8906/'], ['--pretty', 'http://127.0.0.1:8906/']]:
    for out_tty in [False, True]:
        for err_tty in [False, True]:
            run_combo(out_tty, err_tty, args)

server.shutdown()
""}

