package main

import (
    "bufio"
    "bytes"
    "fmt"
    "os/exec"
    "regexp"
    "strings"
)

type curlOption struct {
    takesArg bool
}

func getCurlOptions() map[string]curlOption {
    opts := make(map[string]curlOption)
    cmd := exec.Command("curl", "--help", "all")
    out, err := cmd.Output()
    if err != nil {
        cmd = exec.Command("curl", "--help")
        out, _ = cmd.Output()
    }

    scanner := bufio.NewScanner(bytes.NewReader(out))
    // Match option lines like "-d, --data <data>" or "--abstract-unix-socket <path>" or "-f, --fail"
    optRegex := regexp.MustCompile(`^\s*(?:(-[a-zA-Z0-9]),?\s*)?(?:(--[a-zA-Z0-9\-_.]+))?\s*(<[^>]+>|[A-Z_]{2,})?`)
    for scanner.Scan() {
        line := scanner.Text()
        matches := optRegex.FindStringSubmatch(line)
        if len(matches) > 0 {
            shortOpt := matches[1]
            longOpt := matches[2]
            argPlaceholder := matches[3]
            hasArg := argPlaceholder != ""

            if shortOpt != "" {
                opts[shortOpt] = curlOption{takesArg: hasArg}
            }
            if longOpt != "" {
                opts[longOpt] = curlOption{takesArg: hasArg}
            }
        }
    }
    return opts
}

func main() {
    opts := getCurlOptions()
    testOpts := []string{"-d", "--data", "-f", "--fail", "-u", "--user", "-v", "--verbose", "-i", "--include", "--connect-timeout"}
    for _, opt := range testOpts {
        info, ok := opts[opt]
        fmt.Printf("%-20s found=%-5v takesArg=%-5v\n", opt, ok, info.takesArg)
    }
}
EOF
go run test_opts.go
rm test_opts.go"}

