func formatJSON(v interface{}, depth int, useColor bool) string {
	indent := strings.Repeat("    ", depth)
	nextIndent := strings.Repeat("    ", depth+1)

	switch val := v.(type) {
	case map[string]interface{}:
		if len(val) == 0 {
			if useColor {
				return "\x1b[37m{}\x1b[0m"
			}
			return "{}"
		}
		var sb strings.Builder
		if depth == 0 && useColor {
			sb.WriteString("\x1b[37m{\n")
		} else {
			sb.WriteString("{\n")
		}
		keys := sortedKeys(val)
		for i, k := range keys {
			sb.WriteString(nextIndent)
			if useColor {
				sb.WriteString(fmt.Sprintf("\x1b[34m\"%s\"\x1b[37m: ", k))
			} else {
				sb.WriteString(fmt.Sprintf("\"%s\": ", k))
			}
			sb.WriteString(formatJSONVal(val[k], depth+1, useColor, true))
			if i < len(keys)-1 {
				if useColor {
					sb.WriteString("\x1b[37m,\n")
				} else {
					sb.WriteString(",\n")
				}
			} else {
				sb.WriteString("\n")
			}
		}
		sb.WriteString(indent)
		if useColor {
			sb.WriteString("\x1b[37m}\x1b[0m")
		} else {
			sb.WriteString("}")
		}
		return sb.String()

	case []interface{}:
		if len(val) == 0 {
			if useColor {
				return "\x1b[37m[]\x1b[0m"
			}
			return "[]"
		}
		var sb strings.Builder
		if depth == 0 && useColor {
			sb.WriteString("\x1b[37m[\n")
		} else {
			sb.WriteString("[\n")
		}
		for i, item := range val {
			sb.WriteString(nextIndent)
			sb.WriteString(formatJSONVal(item, depth+1, useColor, false))
			if i < len(val)-1 {
				if useColor {
					sb.WriteString("\x1b[37m,\n")
				} else {
					sb.WriteString(",\n")
				}
			} else {
				sb.WriteString("\n")
			}
		}
		sb.WriteString(indent)
		if useColor {
			sb.WriteString("\x1b[37m]\x1b[0m")
		} else {
			sb.WriteString("]")
		}
		return sb.String()

	default:
		return formatJSONVal(v, depth, useColor, false)
	}
}

func formatJSONVal(v interface{}, depth int, useColor bool, inObject bool) string {
	if !useColor {
		b, _ := json.Marshal(v)
		return string(b)
	}

	switch val := v.(type) {
	case string:
		if inObject {
			return fmt.Sprintf("\x1b[36m\"%s\"", val)
		}
		return fmt.Sprintf("\x1b[34m\"%s\"", val)
	case float64:
		if inObject {
			// Format number, trim trailing .0 if integer
			if val == float64(int64(val)) {
				return fmt.Sprintf("\x1b[36m%d", int64(val))
			}
			return fmt.Sprintf("\x1b[36m%g", val)
		}
		if val == float64(int64(val)) {
			return fmt.Sprintf("%d", int64(val))
		}
		return fmt.Sprintf("%g", val)
	case bool:
		if inObject {
			return fmt.Sprintf("\x1b[35m%t", val)
		}
		return fmt.Sprintf("%t", val)
	case nil:
		if inObject {
			return "\x1b[35mnull"
		}
		return "null"
	case map[string]interface{}, []interface{}:
		return formatJSON(v, depth, useColor)
	default:
		b, _ := json.Marshal(v)
		return string(b)
	}
}

func sortedKeys(m map[string]interface{}) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	// Sort
	for i := 0; i < len(keys); i++ {
		for j := i + 1; j < len(keys); j++ {
			if keys[i] > keys[j] {
				keys[i], keys[j] = keys[j], keys[i]
			}
		}
	}
	return keys
}
