		return false
	}
}

func main() {
	curlOpts := getCurlOptions()
	args := os.Args[1:]

	if len(args) == 0 {
		handleHelp(nil)
		return
	}

	var printCurl, pretty, showHeaders, verbose bool
	var formMode bool

	for _, arg := range args {
		if arg == "--form" || arg == "-F" {
			formMode = true
		} else if arg == "--curl" {
			printCurl = true
		} else if arg == "--pretty" {
			pretty = true
		} else if arg == "-i" {
			showHeaders = true
		} else if arg == "-v" || arg == "--verbose" {
			verbose = true
			showHeaders = true
		} else if arg == "-h" || arg == "--help" {
			handleHelp(args)
			return
		} else if arg == "-V" || arg == "--version" {
			handleVersion()
			return
		}
	}

	var userCurlArgs []string
	var method string
	var rawURL string
	var queryParams []string
	dataMap := make(map[string]interface{})
	var hasDataMap bool
	var hasDataOpt bool
	var hasContentType bool
	var hasAccept bool

	for i := 0; i < len(args); i++ {
		arg := args[i]

		// Intercept curlie-specific flags
		if arg == "--curl" || arg == "--pretty" {
			continue
		}
		if arg == "-i" {
			continue
		}

		// Check if argument is an option
		if strings.HasPrefix(arg, "-") {
			if arg == "-F" || arg == "--form" {
				formMode = true
			}
			if arg == "-d" || arg == "--data" {
				hasDataOpt = true
			}

			if optInfo, ok := curlOpts[arg]; ok {
				if optInfo.takesArg {
					if i+1 < len(args) {
						val := args[i+1]
						if arg == "-H" || arg == "--header" {
							valLower := strings.ToLower(val)
							if strings.HasPrefix(valLower, "content-type:") {
								hasContentType = true
							}
							if strings.HasPrefix(valLower, "accept:") {
								hasAccept = true
							}
						}
						userCurlArgs = append(userCurlArgs, arg, val)
						i++
					} else {
						userCurlArgs = append(userCurlArgs, arg)
					}
				} else {
					userCurlArgs = append(userCurlArgs, arg)
				}
			} else if strings.Contains(arg, "=") {
				// e.g. --connect-timeout=10
				userCurlArgs = append(userCurlArgs, arg)
			} else {
				// Unknown option, treat as 0-arg option
				userCurlArgs = append(userCurlArgs, arg)
			}
			continue
		}

		// Positional argument
		if method == "" && rawURL == "" && isHTTPMethod(arg) {
			method = strings.ToUpper(arg)
			continue
		}

		if rawURL == "" {
			rawURL = arg
			continue
		}

		// Item syntax after URL
		if idx := strings.Index(arg, ":="); idx > 0 {
			key := arg[:idx]
			valStr := arg[idx+2:]
			var parsed interface{}
			if err := json.Unmarshal([]byte(valStr), &parsed); err != nil {
				parsed = nil
			}
			dataMap[key] = parsed
			hasDataMap = true
		} else if idx := strings.Index(arg, "=="); idx > 0 {
			key := arg[:idx]
			valStr := arg[idx+2:]
			queryParams = append(queryParams, key+"="+valStr)
		} else if idx := strings.Index(arg, "="); idx > 0 {
			key := arg[:idx]
			valStr := arg[idx+1:]
			if formMode {
				userCurlArgs = append(userCurlArgs, "-F", key+"="+valStr)
			} else {
				dataMap[key] = valStr
				hasDataMap = true
			}
		} else if idx := strings.Index(arg, ":"); idx > 0 {
			key := arg[:idx]
			if strings.EqualFold(key, "Content-Type") {
				hasContentType = true
			}
			if strings.EqualFold(key, "Accept") {
				hasAccept = true
			}
			userCurlArgs = append(userCurlArgs, "-H", arg)
		} else {
