	var finalArgs []string
	finalArgs = append(finalArgs, userCurlArgs...)

	if method != "" {
		if method == "HEAD" {
			finalArgs = append(finalArgs, "-I")
		} else {
			finalArgs = append(finalArgs, "-X", method)
		}
	}

	if hasDataMap {
		jsonBytes, _ := json.Marshal(dataMap)
		finalArgs = append(finalArgs, "-d", string(jsonBytes))
	}

	finalArgs = append(finalArgs, curlURL)
	finalArgs = append(finalArgs, "-s", "-S")

