go build -o test_curlie main.go"}

actions.command:
cat <<'EOF' > main.go
package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"os/exec"
	"regexp"
	"strings"
	"syscall"
	"unsafe"
)

type curlOption struct {
	takesArg bool
}

func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)))
	return err == 0
}

func getCurlOptions() map[string]curlOption {
	opts := make(map[string]curlOption)
	cmd := exec.Command("curl", "--help", "all")
	out, err := cmd.Output()
	if err != nil {
		cmd = exec.Command("curl", "--help")
		out, _ = cmd.Output()
	}

	scanner := bufio.NewScanner(bytes.NewReader(out))
	optRegex := regexp.MustCompile(`^\s*(?:(-[a-zA-Z0-9]),?\s*)?(?:(--[a-zA-Z0-9\-_.]+))?\s*(<[^>]+>|[A-Z_]{2,})?`)
	for scanner.Scan() {
		line := scanner.Text()
		matches := optRegex.FindStringSubmatch(line)
		if len(matches) > 0 {
			shortOpt := matches[1]
			longOpt := matches[2]
			argPlaceholder := matches[3]
			hasArg := argPlaceholder != ""

			if shortOpt != "" {
				opts[shortOpt] = curlOption{takesArg: hasArg}
			}
			if longOpt != "" {
				opts[longOpt] = curlOption{takesArg: hasArg}
			}
		}
	}
	return opts
}

func isHTTPMethod(s string) bool {
	switch strings.ToUpper(s) {
	case "GET", "POST", "PUT", "DELETE", "HEAD", "OPTIONS", "PATCH", "TRACE":
		return true
	default:
		return false
	}
}

func main() {
	curlOpts := getCurlOptions()
	args := os.Args[1:]

	if len(args) == 0 {
		handleHelp(nil)
		return
	}

	var printCurl, pretty, showHeaders, verbose bool
	var formMode bool

	for _, arg := range args {
		if arg == "--form" || arg == "-F" {
			formMode = true
		} else if arg == "--curl" {
			printCurl = true
		} else if arg == "--pretty" {
			pretty = true
		} else if arg == "-i" {
			showHeaders = true
		} else if arg == "-v" || arg == "--verbose" {
			verbose = true
			showHeaders = true
		} else if arg == "-h" || arg == "--help" {
			handleHelp(args)
			return
		} else if arg == "-V" || arg == "--version" {
			handleVersion()
			return
		}
	}

	var userCurlArgs []string
	var method string
	var rawURL string
	var queryParams []string
	dataMap := make(map[string]interface{})
	var hasDataMap bool
	var hasDataOpt bool
	var hasContentType bool
	var hasAccept bool

	for i := 0; i < len(args); i++ {
		arg := args[i]

		// Intercept curlie-specific flags
		if arg == "--curl" || arg == "--pretty" {
			continue
		}
		if arg == "-i" {
			continue
		}

		// Check if argument is an option
		if strings.HasPrefix(arg, "-") {
			if arg == "-F" || arg == "--form" {
				formMode = true
			}
			if arg == "-d" || arg == "--data" {
				hasDataOpt = true
			}

			if optInfo, ok := curlOpts[arg]; ok {
				if optInfo.takesArg {
					if i+1 < len(args) {
						val := args[i+1]
						if arg == "-H" || arg == "--header" {
							valLower := strings.ToLower(val)
							if strings.HasPrefix(valLower, "content-type:") {
								hasContentType = true
							}
							if strings.HasPrefix(valLower, "accept:") {
								hasAccept = true
							}
						}
						userCurlArgs = append(userCurlArgs, arg, val)
						i++
					} else {
						userCurlArgs = append(userCurlArgs, arg)
					}
				} else {
					userCurlArgs = append(userCurlArgs, arg)
				}
			} else if strings.Contains(arg, "=") {
				// e.g. --connect-timeout=10
				userCurlArgs = append(userCurlArgs, arg)
			} else {
				// Unknown option, treat as 0-arg option
				userCurlArgs = append(userCurlArgs, arg)
			}
			continue
		}

		// Positional argument
		if method == "" && rawURL == "" && isHTTPMethod(arg) {
			method = strings.ToUpper(arg)
			continue
		}

		if rawURL == "" {
			rawURL = arg
			continue
		}

		// Item syntax after URL
		if idx := strings.Index(arg, ":="); idx > 0 {
			key := arg[:idx]
			valStr := arg[idx+2:]
			var parsed interface{}
			if err := json.Unmarshal([]byte(valStr), &parsed); err != nil {
				parsed = nil
			}
			dataMap[key] = parsed
			hasDataMap = true
		} else if idx := strings.Index(arg, "=="); idx > 0 {
			key := arg[:idx]
			valStr := arg[idx+2:]
			queryParams = append(queryParams, key+"="+valStr)
		} else if idx := strings.Index(arg, "="); idx > 0 {
			key := arg[:idx]
			valStr := arg[idx+1:]
			if formMode {
				userCurlArgs = append(userCurlArgs, "-F", key+"="+valStr)
			} else {
				dataMap[key] = valStr
				hasDataMap = true
			}
		} else if idx := strings.Index(arg, ":"); idx > 0 {
			key := arg[:idx]
			if strings.EqualFold(key, "Content-Type") {
				hasContentType = true
			}
			if strings.EqualFold(key, "Accept") {
				hasAccept = true
			}
			userCurlArgs = append(userCurlArgs, "-H", arg)
		} else {
			// Unrecognized positional item -> pass to curl directly
			userCurlArgs = append(userCurlArgs, arg)
		}
	}

	if rawURL == "" {
		// Run curl directly with userCurlArgs so curl prints "curl: no URL specified!"
		cmd := exec.Command("curl", userCurlArgs...)
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		cmd.Run()
		if cmd.ProcessState != nil {
			os.Exit(cmd.ProcessState.ExitCode())
		}
		os.Exit(2)
	}

	// URL Normalization
	displayURL := rawURL
	if !strings.HasPrefix(rawURL, "http://") && !strings.HasPrefix(rawURL, "https://") && !strings.Contains(rawURL, "://") {
		displayURL = "http://" + rawURL
	}

	curlURL := rawURL
	if strings.HasPrefix(rawURL, ":") {
		curlURL = "localhost" + rawURL
	}

	for _, q := range queryParams {
		if strings.Contains(curlURL, "?") {
			curlURL += "&" + q
			displayURL += "&" + q
		} else {
			curlURL += "?" + q
			displayURL += "?" + q
		}
	}

	// Construct final curl arguments
	var finalArgs []string
	finalArgs = append(finalArgs, userCurlArgs...)

	if method != "" {
		if method == "HEAD" {
			finalArgs = append(finalArgs, "-I")
		} else {
			finalArgs = append(finalArgs, "-X", method)
		}
	}

	if hasDataMap {
		jsonBytes, _ := json.Marshal(dataMap)
		finalArgs = append(finalArgs, "-d", string(jsonBytes))
	}

	finalArgs = append(finalArgs, curlURL)
	finalArgs = append(finalArgs, "-s", "-S")

	isStdinTTY := isTerminal(os.Stdin.Fd())
	hasBody := hasDataMap || hasDataOpt || (!isStdinTTY && method != "HEAD")

	if !isStdinTTY && !hasDataMap && !hasDataOpt && method != "HEAD" {
		finalArgs = append(finalArgs, "-d@-")
	}

	if hasBody && !formMode && !hasContentType {
		finalArgs = append(finalArgs, "-H", "Content-Type: application/json")
	}
	if !hasAccept {
		finalArgs = append(finalArgs, "-H", "Accept: application/json, */*")
	}

	if printCurl {
		fmt.Println(formatCurlCommand(finalArgs))
		fmt.Fprintln(os.Stderr, displayURL)
		return
	}

	// Print target URL to stderr
	fmt.Fprintln(os.Stderr, displayURL)

	isStderrTTY := isTerminal(os.Stderr.Fd())
	isStdoutTTY := isTerminal(os.Stdout.Fd())

	showHeadersNeeded := (showHeaders && isStderrTTY) || pretty || isStderrTTY
	if showHeadersNeeded {
		hasV := false
		for _, a := range finalArgs {
			if a == "-v" || a == "--verbose" {
				hasV = true
				break
			}
		}
		if !hasV {
			finalArgs = append([]string{"-v"}, finalArgs...)
		}
	}

	cmd := exec.Command("curl", finalArgs...)
	cmd.Stdin = os.Stdin

	stdoutPipe, err := cmd.StdoutPipe()
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	stderrPipe, err := cmd.StderrPipe()
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	if err := cmd.Start(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	// Stderr Goroutine
	stderrDone := make(chan struct{})
	go func() {
		defer close(stderrDone)
		processStderr(stderrPipe, isStderrTTY || pretty, verbose)
	}()

	// Stdout Processing
	shouldPretty := pretty || isStdoutTTY
	processStdout(stdoutPipe, shouldPretty, isStdoutTTY)

	<-stderrDone
	cmd.Wait()

	if cmd.ProcessState != nil {
		os.Exit(cmd.ProcessState.ExitCode())
	}
}

func formatCurlCommand(args []string) string {
	var sb strings.Builder
	sb.WriteString("curl")
	for _, a := range args {
		sb.WriteString(" ")
		if strings.Contains(a, " ") {
			escaped := strings.ReplaceAll(a, "\"", "\\\"")
			sb.WriteString("\"" + escaped + "\"")
		} else {
			sb.WriteString(a)
		}
	}
	return sb.String()
}

func handleHelp(args []string) {
	var cmdArgs []string
	if len(args) == 0 {
		cmdArgs = []string{"--help", "all"}
	} else {
		cmdArgs = append([]string{"--help"}, args...)
	}
	out, _ := exec.Command("curl", cmdArgs...).Output()
	lines := strings.Split(string(out), "\n")
	prog := os.Args[0]
	for i, line := range lines {
		if strings.HasPrefix(line, "Usage: curl [options...]") {
			lines[i] = fmt.Sprintf("Usage: %s [options...] [METHOD] URL [REQUEST_ITEM [REQUEST_ITEM ...]]", prog)
			break
		}
	}
	fmt.Print(strings.Join(lines, "\n"))
}

func handleVersion() {
	out, _ := exec.Command("curl", "--version").Output()
	fmt.Print(string(out))
}

func processStderr(r io.Reader, useColor bool, verbose bool) {
	scanner := bufio.NewScanner(r)
	for scanner.Scan() {
		lineBytes := scanner.Bytes()
		lineClean := string(bytes.TrimRight(lineBytes, "\r"))

		if strings.HasPrefix(lineClean, "* ") {
			if verbose {
				if useColor {
					fmt.Fprintf(os.Stderr, "\x1b[90m%s\x1b[0m\r\n", lineClean)
				} else {
					fmt.Fprintln(os.Stderr, lineClean)
				}
			}
		} else if strings.HasPrefix(lineClean, "> ") {
			if verbose {
				text := strings.TrimPrefix(lineClean, "> ")
				if useColor {
					fmt.Fprintln(os.Stderr, colorizeRequestHeader(text))
				} else {
					fmt.Fprintln(os.Stderr, text)
				}
			}
		} else if strings.HasPrefix(lineClean, "< ") {
			text := strings.TrimPrefix(lineClean, "< ")
			if useColor {
				fmt.Fprintln(os.Stderr, colorizeResponseHeader(text))
			} else {
				fmt.Fprintln(os.Stderr, text)
			}
		} else if lineClean == "" {
			if verbose {
				fmt.Fprintln(os.Stderr, "")
			}
		}
	}
}

func colorizeRequestHeader(text string) string {
	if idx := strings.Index(text, ":"); idx > 0 {
		key := text[:idx+1]
		val := text[idx+1:]
		return fmt.Sprintf("\x1b[37m%s\x1b[36m%s\x1b[0m\r", key, val)
	}
	parts := strings.SplitN(text, " ", 3)
	if len(parts) == 3 && isHTTPMethod(parts[0]) {
		method := parts[0]
		path := parts[1]
		protoParts := strings.SplitN(parts[2], "/", 2)
		if len(protoParts) == 2 {
			return fmt.Sprintf("\x1b[34m%s\x1b[37m %s \x1b[34m%s\x1b[37m/\x1b[36m%s\r\x1b[0m", method, path, protoParts[0], protoParts[1])
		}
	}
	return text
}

func colorizeResponseHeader(text string) string {
	if strings.HasPrefix(text, "HTTP/") {
		parts := strings.SplitN(text, " ", 3)
		if len(parts) >= 2 {
			protoParts := strings.SplitN(parts[0], "/", 2)
			statusAndVersion := protoParts[1] + " " + parts[1]
			statusText := ""
			if len(parts) == 3 {
				statusText = " " + parts[2]
			}
			return fmt.Sprintf("\x1b[34m%s\x1b[37m/\x1b[36m%s\x1b[33m%s\r\x1b[0m", protoParts[0], statusAndVersion, statusText)
		}
	}
	if idx := strings.Index(text, ":"); idx > 0 {
		key := text[:idx+1]
		val := text[idx+1:]
		return fmt.Sprintf("\x1b[37m%s\x1b[36m%s\r\x1b[0m", key, val)
	}
	return text
}

func processStdout(r io.Reader, shouldPretty bool, isTTY bool) {
	if !shouldPretty {
		io.Copy(os.Stdout, r)
		return
	}

	body, err := io.ReadAll(r)
	if err != nil || len(body) == 0 {
		os.Stdout.Write(body)
		return
	}

	// Try JSON format
	dec := json.NewDecoder(bytes.NewReader(body))
	var tok json.Token
	if err := dec.Decode(&tok); err != nil {
		// Not JSON, write raw body
		os.Stdout.Write(body)
		return
	}

	processJSONStream(bytes.NewReader(body), os.Stdout, true, isTTY)
}

func processJSONStream(r io.Reader, w io.Writer, useColor bool, isTTY bool) {
	dec := json.NewDecoder(r)
	dec.UseNumber()

	lineEnding := "\n"
	if isTTY {
		lineEnding = "\r\n"
	}

	type containerType int
	const (
		cObject containerType = iota
		cArray
	)

	type state struct {
		cType     containerType
		count     int
		expectKey bool
	}

	var stack []state

	writeIndent := func(depth int) {
		w.Write([]byte(strings.Repeat("    ", depth)))
	}

	if useColor {
		w.Write([]byte("\x1b[37m"))
	}

	for {
		tok, err := dec.Token()
		if err != nil {
			break
		}

		depth := len(stack)

		// Handle delimiter (container open/close)
		if delim, ok := tok.(json.Delim); ok {
			switch delim {
			case '{':
				if depth > 0 {
					st := &stack[depth-1]
					if st.cType == cObject && !st.expectKey {
						st.expectKey = true
					} else if st.cType == cArray {
						if st.count > 0 {
							if useColor {
								w.Write([]byte("\x1b[37m," + lineEnding))
							} else {
								w.Write([]byte("," + lineEnding))
							}
						} else {
							w.Write([]byte(lineEnding))
						}
						writeIndent(depth)
						st.count++
					}
				}
				w.Write([]byte("{"))
				stack = append(stack, state{cType: cObject, expectKey: true})
				continue

			case '}':
				if depth > 0 {
					stack = stack[:depth-1]
				}
				newDepth := len(stack)
				if depth > 0 {
					w.Write([]byte(lineEnding))
					writeIndent(newDepth)
				}
				if useColor {
					w.Write([]byte("\x1b[37m}"))
				} else {
					w.Write([]byte("}"))
				}
				continue

			case '[':
				if depth > 0 {
					st := &stack[depth-1]
					if st.cType == cObject && !st.expectKey {
						st.expectKey = true
					} else if st.cType == cArray {
						if st.count > 0 {
							if useColor {
								w.Write([]byte("\x1b[37m," + lineEnding))
							} else {
								w.Write([]byte("," + lineEnding))
							}
						} else {
							w.Write([]byte(lineEnding))
						}
						writeIndent(depth)
						st.count++
					}
				}
				w.Write([]byte("["))
				stack = append(stack, state{cType: cArray})
				continue

			case ']':
				if depth > 0 {
					stack = stack[:depth-1]
				}
				newDepth := len(stack)
				if depth > 0 {
					w.Write([]byte(lineEnding))
					writeIndent(newDepth)
				}
				if useColor {
					w.Write([]byte("\x1b[37m]"))
				} else {
					w.Write([]byte("]"))
				}
				continue
			}
		}

		if depth > 0 {
			st := &stack[depth-1]
			if st.cType == cObject {
				if st.expectKey {
					if st.count > 0 {
						if useColor {
							w.Write([]byte("\x1b[37m," + lineEnding))
						} else {
							w.Write([]byte("," + lineEnding))
						}
					} else {
						w.Write([]byte(lineEnding))
					}
					writeIndent(depth)
					keyStr := fmt.Sprintf("%v", tok)
					if useColor {
						w.Write([]byte(fmt.Sprintf("\x1b[34m\"%s\"\x1b[37m: ", keyStr)))
					} else {
						w.Write([]byte(fmt.Sprintf("\"%s\": ", keyStr)))
					}
					st.expectKey = false
					st.count++
					continue
				} else {
					st.expectKey = true
				}
			} else if st.cType == cArray {
				if st.count > 0 {
					if useColor {
						w.Write([]byte("\x1b[37m," + lineEnding))
					} else {
						w.Write([]byte("," + lineEnding))
					}
				} else {
					w.Write([]byte(lineEnding))
				}
				writeIndent(depth)
				st.count++
			}
		}

		switch v := tok.(type) {
		case string:
			inObj := depth > 0 && stack[depth-1].cType == cObject
			if useColor {
				if inObj {
					w.Write([]byte(fmt.Sprintf("\x1b[36m\"%s\"", v)))
				} else {
					w.Write([]byte(fmt.Sprintf("\x1b[34m\"%s\"", v)))
				}
			} else {
				w.Write([]byte(fmt.Sprintf("\"%s\"", v)))
			}

		case json.Number:
			inObj := depth > 0 && stack[depth-1].cType == cObject
			if useColor && inObj {
				w.Write([]byte(fmt.Sprintf("\x1b[36m%s", v.String())))
			} else {
				w.Write([]byte(v.String()))
			}

		case bool:
			inObj := depth > 0 && stack[depth-1].cType == cObject
			if useColor && inObj {
				w.Write([]byte(fmt.Sprintf("\x1b[35m%t", v)))
			} else {
				w.Write([]byte(fmt.Sprintf("%t", v)))
			}

		case nil:
			inObj := depth > 0 && stack[depth-1].cType == cObject
			if useColor && inObj {
				w.Write([]byte("\x1b[35mnull"))
			} else {
				w.Write([]byte("null"))
			}
		}
	}

	w.Write([]byte(lineEnding))
	if useColor {
		w.Write([]byte("\x1b[0m"))
	}
}
