func colorizeResponseHeader(text string) string {
	textClean := strings.TrimRight(text, "\r")
	if strings.HasPrefix(textClean, "HTTP/") {
		parts := strings.SplitN(textClean, " ", 3)
		if len(parts) >= 2 {
			protoParts := strings.SplitN(parts[0], "/", 2)
			statusAndVersion := protoParts[1] + " " + parts[1]
			statusText := ""
			if len(parts) == 3 {
