	optRegex := regexp.MustCompile(`^\s*(?:(-[a-zA-Z0-9]),?\s*)?(?:(--[a-zA-Z0-9\-_.]+))?\s*(<[^>]+>|[A-Z_]{2,})?`)
	for scanner.Scan() {
		line := scanner.Text()
		matches := optRegex.FindStringSubmatch(line)
		if len(matches) > 0 {
			shortOpt := matches[1]
			longOpt := matches[2]
			argPlaceholder := matches[3]
			hasArg := argPlaceholder != ""

			if shortOpt != "" {
				opts[shortOpt] = curlOption{takesArg: hasArg}
			}
			if longOpt != "" {
				opts[longOpt] = curlOption{takesArg: hasArg}
			}
		}
	}
	return opts
}

func isHTTPMethod(s string) bool {
	switch strings.ToUpper(s) {
	case "GET", "POST", "PUT", "DELETE", "HEAD", "OPTIONS", "PATCH", "TRACE":
		return true
	default:
		return false
	}
}

