		if strings.HasPrefix(line, "* ") {
			if verbose {
				lineClean := strings.TrimRight(line, "\r\n")
				if useColor {
					fmt.Fprintf(os.Stderr, "\x1b[90m%s\x1b[0m\n", lineClean)
				} else {
					fmt.Fprintln(os.Stderr, lineClean)
				}
			}
		} else if strings.HasPrefix(line, "> ") {
			if verbose {
				text := strings.TrimPrefix(line, "> ")
				textClean := strings.TrimRight(text, "\r\n")
