	}
	if idx := strings.Index(textClean, ":"); idx > 0 {
		key := textClean[:idx+1]
		val := textClean[idx+1:]
		return fmt.Sprintf("\x1b[37m%s\x1b[36m%s\r\x1b[0m", key, val)
	}
	return textClean
}

func processStdout(r io.Reader, shouldPretty bool, isTTY bool) {
	if !shouldPretty {
		io.Copy(os.Stdout, r)
		return
