	}

	for {
		tok, err := dec.Token()
		if err != nil {
			break
		}

		depth := len(stack)

		// Handle delimiter (container open/close)
		if delim, ok := tok.(json.Delim); ok {
			switch delim {
			case '{':
				if depth > 0 {
					st := &stack[depth-1]
					if st.cType == cObject && !st.expectKey {
						st.expectKey = true
					} else if st.cType == cArray {
						if st.count > 0 {
							if useColor {
								w.Write([]byte("\x1b[37m," + lineEnding))
							} else {
								w.Write([]byte("," + lineEnding))
							}
						} else {
							w.Write([]byte(lineEnding))
						}
						writeIndent(depth)
						st.count++
					}
				}
				w.Write([]byte("{"))
				stack = append(stack, state{cType: cObject, expectKey: true})
				continue

			case '}':
				if depth > 0 {
					stack = stack[:depth-1]
				}
				newDepth := len(stack)
				if depth > 0 {
					w.Write([]byte(lineEnding))
					writeIndent(newDepth)
				}
				if useColor {
					w.Write([]byte("\x1b[37m}"))
				} else {
					w.Write([]byte("}"))
				}
				continue

			case '[':
				if depth > 0 {
					st := &stack[depth-1]
					if st.cType == cObject && !st.expectKey {
						st.expectKey = true
					} else if st.cType == cArray {
						if st.count > 0 {
							if useColor {
								w.Write([]byte("\x1b[37m," + lineEnding))
							} else {
								w.Write([]byte("," + lineEnding))
							}
						} else {
							w.Write([]byte(lineEnding))
						}
						writeIndent(depth)
						st.count++
					}
				}
				w.Write([]byte("["))
				stack = append(stack, state{cType: cArray})
				continue

			case ']':
				if depth > 0 {
					stack = stack[:depth-1]
				}
				newDepth := len(stack)
				if depth > 0 {
					w.Write([]byte(lineEnding))
					writeIndent(newDepth)
				}
				if useColor {
					w.Write([]byte("\x1b[37m]"))
				} else {
					w.Write([]byte("]"))
				}
				continue
			}
		}

		if depth > 0 {
			st := &stack[depth-1]
			if st.cType == cObject {
				if st.expectKey {
					if st.count > 0 {
						if useColor {
							w.Write([]byte("\x1b[37m," + lineEnding))
						} else {
							w.Write([]byte("," + lineEnding))
						}
					} else {
						w.Write([]byte(lineEnding))
					}
					writeIndent(depth)
					keyStr := fmt.Sprintf("%v", tok)
					if useColor {
						w.Write([]byte(fmt.Sprintf("\x1b[34m\"%s\"\x1b[37m: ", keyStr)))
					} else {
						w.Write([]byte(fmt.Sprintf("\"%s\": ", keyStr)))
					}
					st.expectKey = false
					st.count++
					continue
				} else {
					st.expectKey = true
				}
			} else if st.cType == cArray {
				if st.count > 0 {
					if useColor {
						w.Write([]byte("\x1b[37m," + lineEnding))
					} else {
						w.Write([]byte("," + lineEnding))
					}
				} else {
					w.Write([]byte(lineEnding))
				}
				writeIndent(depth)
				st.count++
			}
		}

		switch v := tok.(type) {
		case string:
			inObj := depth > 0 && stack[depth-1].cType == cObject
			if useColor {
				if inObj {
					w.Write([]byte(fmt.Sprintf("\x1b[36m\"%s\"", v)))
				} else {
					w.Write([]byte(fmt.Sprintf("\x1b[34m\"%s\"", v)))
				}
			} else {
				w.Write([]byte(fmt.Sprintf("\"%s\"", v)))
			}

		case json.Number:
			inObj := depth > 0 && stack[depth-1].cType == cObject
			if useColor && inObj {
				w.Write([]byte(fmt.Sprintf("\x1b[36m%s", v.String())))
			} else {
				w.Write([]byte(v.String()))
			}

		case bool:
			inObj := depth > 0 && stack[depth-1].cType == cObject
			if useColor && inObj {
				w.Write([]byte(fmt.Sprintf("\x1b[35m%t", v)))
			} else {
				w.Write([]byte(fmt.Sprintf("%t", v)))
			}

		case nil:
			inObj := depth > 0 && stack[depth-1].cType == cObject
			if useColor && inObj {
				w.Write([]byte("\x1b[35mnull"))
			} else {
				w.Write([]byte("null"))
			}
		}
	}

	w.Write([]byte(lineEnding))
	if useColor {
		w.Write([]byte("\x1b[0m"))
	}
}
EOF
go build -o test_curlie main.go"}

